#!/usr/bin/env node
/**
 * Solo analysis of NSW Warrior Path candidates.
 * Uses Presidio-anonymized data only.
 * Scores candidates on 6 factors for contract likelihood.
 */
const fs = require('fs');
const data = JSON.parse(fs.readFileSync('.fastops/_nsw-candidates-anon.json', 'utf8'));

// PST MINIMUM STANDARDS (official NSW/CNATT)
const PST_STANDARDS = {
  'SEAL':           { swim: 12.5, pushups: 50, situps: 50, run: 10.5, pullups: 10 },
  'SWCC':           { swim: 13.0, pushups: 50, situps: 50, run: 12.5, pullups: 10 },
  'Diver':          { swim: 14.0, pushups: 42, situps: 50, run: 12.75, pullups: 6 },
  'Rescue swimmer': { swim: 12.0, pushups: 42, situps: 50, run: 12.0, pullups: 6 },
  'SARC':           { swim: 12.5, pushups: 50, situps: 50, run: 10.5, pullups: 10 },
  'HMATF':          { swim: 14.0, pushups: 42, situps: 50, run: 12.75, pullups: 6 },
};

function parseTime(str) {
  if (!str || str === '' || str === '0.0' || str === '0' || str === 'DNF' || str === '0.00') return null;
  str = String(str).trim().replace(/O/g, '0'); // fix letter-O typos
  let parts;
  if (str.includes(':')) parts = str.split(':');
  else if (str.includes('.')) parts = str.split('.');
  else return null;
  if (parts.length !== 2) return null;
  const mins = parseInt(parts[0]);
  const secs = parseInt(parts[1]);
  if (isNaN(mins) || isNaN(secs)) return null;
  return mins + secs / 60;
}

function parseNum(str) {
  if (!str || str === '') return null;
  const n = parseInt(String(str));
  return isNaN(n) ? null : n;
}

function xlDate(n) {
  if (!n || typeof n !== 'number') return null;
  return new Date((n - 25569) * 86400000);
}

const today = new Date('2026-03-31');

// Filter to real candidates
const candidates = data.filter(d =>
  d.program && !['Program', 'Assign'].includes(d.program) &&
  d.navyStatus && d.navyStatus !== 'Navy Status' && d.navyStatus !== 'Please update'
);

console.log('Analyzing ' + candidates.length + ' real candidates...\n');

const results = [];

for (const c of candidates) {
  const std = PST_STANDARDS[c.program];
  if (!std) continue;

  const shipDate = xlDate(c.shipDate);
  const daysToShip = shipDate ? Math.round((shipDate - today) / 86400000) : null;

  const swim = parseTime(c.swim);
  const pushups = parseNum(c.pushups);
  const situps = parseNum(c.situps);
  const run = parseTime(c.run);
  const pullups = parseNum(c.pullups);

  const swimPass = swim !== null && swim <= std.swim;
  const pushPass = pushups !== null && pushups >= std.pushups;
  const sitPass = situps !== null && situps >= std.situps;
  const runPass = run !== null && run <= std.run;
  const pullPass = pullups !== null && pullups >= std.pullups;

  const hasAllScores = swim !== null && pushups !== null && situps !== null && run !== null && pullups !== null;
  const passesAll = swimPass && pushPass && sitPass && runPass && pullPass;
  const eventsPass = [swimPass, pushPass, sitPass, runPass, pullPass].filter(Boolean).length;
  const eventsTested = [swim, pushups, situps, run, pullups].filter(v => v !== null).length;

  let likelihood = 0;
  let reasons = [];
  let risks = [];

  // Factor 1: PST passing (40 pts max)
  if (c.pst === 'Pass' && passesAll) {
    likelihood += 40; reasons.push('PST PASS (all events verified)');
  } else if (c.pst === 'Pass') {
    likelihood += 30; reasons.push('PST marked pass');
  } else if (eventsPass >= 4 && eventsTested >= 5) {
    likelihood += 20; reasons.push(eventsPass + '/5 events pass');
  } else if (eventsPass >= 3) {
    likelihood += 10; reasons.push(eventsPass + '/5 events pass');
  } else if (c.pst === 'Fail') {
    risks.push('PST FAIL (' + eventsPass + '/' + eventsTested + ' events)');
  } else {
    risks.push('No PST scores');
  }

  // Factor 2: Contract status (20 pts max)
  if (c.navyStatus === 'Contracted') {
    likelihood += 20; reasons.push('Contracted');
  } else if (c.navyStatus === 'In Dep') {
    likelihood += 10; reasons.push('In DEP');
  } else {
    risks.push('Not contracted: ' + c.navyStatus);
  }

  // Factor 3: Time to ship (15 pts max)
  if (daysToShip !== null) {
    if (daysToShip < 0) {
      risks.push('Ship date PASSED (' + daysToShip + 'd)');
    } else if (daysToShip <= 30) {
      if (c.pst === 'Pass') { likelihood += 15; reasons.push('Ships <30d + passing'); }
      else { likelihood += 5; risks.push('Ships <30d but NOT passing'); }
    } else if (daysToShip <= 90) {
      likelihood += 12; reasons.push('Ships 30-90d');
    } else {
      likelihood += 8; reasons.push('Ships 90+d');
    }
  } else {
    risks.push('No ship date');
  }

  // Factor 4: Assessment (10 pts max)
  if (c.assessment === 'Ready to ship') { likelihood += 10; reasons.push('Ready to ship'); }
  else if (c.assessment === '30 days out') { likelihood += 8; reasons.push('30 days out'); }
  else if (c.assessment === '60 days out') { likelihood += 6; reasons.push('60 days out'); }
  else if (c.assessment === 'Ready to contract') { likelihood += 5; reasons.push('Ready to contract'); }
  else if (c.assessment === 'NSW ENGAGED') { likelihood += 4; reasons.push('NSW engaged'); }
  else if (c.assessment === 'Progressing TBD') { likelihood += 3; reasons.push('Progressing'); }
  else if (c.assessment === 'At Risk') { likelihood -= 5; risks.push('AT RISK assessment'); }
  else if (c.assessment === 'Not a player') { likelihood -= 10; risks.push('NOT A PLAYER'); }

  // Factor 5: PST count / engagement (5 pts max)
  const pstCount = parseNum(c.pstCount);
  if (pstCount && pstCount >= 3) { likelihood += 5; reasons.push(pstCount + ' PSTs taken'); }
  else if (pstCount && pstCount >= 1) { likelihood += 3; }

  // Factor 6: Composite/effort/alignment (10 pts max)
  const comp = parseNum(c.compositeScore);
  const effort = parseNum(c.effortScore);
  const align = parseNum(c.nswAlignment);
  if (comp && comp >= 50) { likelihood += 5; reasons.push('High composite: ' + comp); }
  else if (comp && comp >= 30) { likelihood += 3; }
